llm_calls.content:
{
  "task_summary": "Predict whether an individual’s income-to-poverty ratio falls below the task threshold using ACS person-level attributes.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 17,
      "rationale": "Employment status is directly tied to current earnings and labor-force attachment, making it highly predictive across states."
    },
    {
      "rank": 2,
      "feature_id": 18,
      "rationale": "Occupation captures broad job quality and pay structure that generalize better than state-specific context."
    },
    {
      "rank": 3,
      "feature_id": 19,
      "rationale": "Usual weekly hours worked is a strong proxy for labor supply and income level."
    },
    {
      "rank": 4,
      "feature_id": 1,
      "rationale": "Education is a stable predictor of earning potential and poverty risk across geographies."
    },
    {
      "rank": 5,
      "feature_id": 0,
      "rationale": "Age strongly relates to labor-market stage, schooling completion, and retirement status."
    },
    {
      "rank": 6,
      "feature_id": 2,
      "rationale": "Marital status can proxy household economic resources and shared expenses, though less directly than labor variables."
    },
    {
      "rank": 7,
      "feature_id": 11,
      "rationale": "Household relationship helps distinguish children, spouses, and household heads, which affects income-to-poverty patterns."
    },
    {
      "rank": 8,
      "feature_id": 4,
      "rationale": "Disability is a meaningful predictor of labor-force participation and economic hardship across states."
    },
    {
      "rank": 9,
      "feature_id": 14,
      "rationale": "Cognitive difficulty can affect employment and earnings, but may be noisier and more sensitive to reporting variation."
    },
    {
      "rank": 10,
      "feature_id": 12,
      "rationale": "Hearing difficulty is relevant to work capacity and income, though typically weaker than core labor variables."
    },
    {
      "rank": 11,
      "feature_id": 13,
      "rationale": "Vision difficulty can reduce employment opportunities and earnings, but is usually a secondary signal."
    },
    {
      "rank": 12,
      "feature_id": 3,
      "rationale": "Sex can correlate with labor-market outcomes, but it is a demographic shortcut and should be downweighted."
    },
    {
      "rank": 13,
      "feature_id": 15,
      "rationale": "Race is often predictive through structural inequality, but it is also a sensitive demographic proxy and less semantically causal."
    },
    {
      "rank": 14,
      "feature_id": 10,
      "rationale": "Nativity captures immigrant status, which can relate to earnings, but may vary in meaning across states and subpopulations."
    },
    {
      "rank": 15,
      "feature_id": 7,
      "rationale": "Citizenship is related to labor-market access and eligibility, but overlaps with nativity and can encode demographic shortcuts."
    },
    {
      "rank": 16,
      "feature_id": 6,
      "rationale": "Recent mobility may reflect housing instability or migration, but it is more likely to pick up geographic shift artifacts."
    },
    {
      "rank": 17,
      "feature_id": 9,
      "rationale": "Ancestry is weakly and indirectly related to income, with substantial risk of encoding ethnicity-specific shortcuts."
    },
    {
      "rank": 18,
      "feature_id": 8,
      "rationale": "Military service status is only relevant for a subset of people and can be state- and cohort-dependent."
    },
    {
      "rank": 19,
      "feature_id": 16,
      "rationale": "Grandparent-care status is niche and likely sparse, making it less robust for cross-state generalization."
    },
    {
      "rank": 20,
      "feature_id": 5,
      "rationale": "Parent employment status is mainly defined for children and is least broadly applicable for predicting an individual’s poverty ratio."
    }
  ]
}
